from pathlib import Path
from html import escape
import re,json
root=Path(__file__).resolve().parents[1]
dist=root/'dist'
home=(dist/'index.html').read_text()
header=home[home.index('<a class="skip"'):home.index('<main')]
footer=home[home.index('<footer'):home.index('</body>')]
origin='https://coppeyboisdefeu.ch'
org={'@context':'https://schema.org','@type':'Organization','@id':origin+'/#entreprise','name':'Coppey Bois de feu','url':origin+'/','telephone':'+41792903493','logo':origin+'/assets/logo.svg'}
def photo(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="/assets/{name}-1200.webp" srcset="/assets/{name}-600.webp 600w, /assets/{name}-1200.webp 1200w, /assets/{name}-2000.webp 2000w" sizes="(max-width:767px) 100vw, 50vw" width="1200" height="900" alt="{alt}" loading="{"eager" if eager else "lazy"}">'
def cta(title='On prépare votre bois ?',label='Préparer ma demande'):
 return f'<section class="small-cta"><h2>{title}</h2><a class="button" href="/reservation/">{label} <span aria-hidden="true">↗</span></a></section>'
def write(slug,title,desc,body):
 dest=dist/slug;dest.mkdir(exist_ok=True)
 crumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Accueil','item':origin+'/'},{'@type':'ListItem','position':2,'name':title.split(' | ')[0],'item':origin+'/'+slug+'/'}]}
 styles='<link rel="stylesheet" href="/style.css">'
 # Preserve the official font embed when a web project has been supplied.
 embed=re.search(r'<link[^>]+href="https://use\.typekit\.net/[^\"]+"[^>]*>',home)
 if embed: styles=embed[0]+styles
 meta=f'<meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{origin}/{slug}/">'
 html=f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{origin}/{slug}/"><link rel="icon" href="/assets/embleme.svg" type="image/svg+xml">{meta}{styles}<script src="/site.js" defer></script><script type="application/ld+json">{json.dumps(org,ensure_ascii=False)}</script><script type="application/ld+json">{json.dumps(crumb,ensure_ascii=False)}</script></head><body>{header}<main id="contenu">{body}</main>{footer}</body></html>'
 (dest/'index.html').write_text(html)
bois=f'''
<section class="page-head"><a class="back-link" href="/">Accueil / Le bois</a><h1>Le bois,<br>tout simplement.</h1><p>Tout commence par votre foyer. La place disponible, la longueur des bûches et vos habitudes nous aident à préparer votre demande.</p></section>
<section class="wood-story section"><div>{photo('bois-detail','Détail des cernes et de l’écorce des grumes de Coppey',eager=True)}</div><div><h2>Avant de choisir,<br>regardez votre foyer.</h2><p>Poêle ou cheminée : relevez la longueur de bûche indiquée par le fabricant. Si vous avez un doute, joignez une photo de votre installation à votre message WhatsApp.</p><p>Coppey vous précisera les essences, les longueurs et les conditionnements disponibles pour votre demande.</p><a class="text-link" href="/reservation/?besoin=conseil">Demander un conseil <span aria-hidden="true">↗</span></a></div></section>
<section class="space-tool section" aria-labelledby="tool-title"><div class="space-tool__intro"><h2 id="tool-title">Combien de stères<br>chez vous ?</h2><p>Mesurez votre rangement et choisissez la longueur des bûches pour estimer combien de stères peuvent y tenir.</p><p class="small-copy">Estimation pour du bois bien empilé. Le rangement et le format des bûches font varier le résultat. À confirmer avec Coppey.</p></div><div class="space-tool__surface"><div class="space-visual" aria-hidden="true"><img src="/assets/buches-creme.svg" width="150" height="160" alt=""><div class="space-rule"></div></div><div class="space-result"><output id="space-volume" for="space-width space-depth space-height space-length">≈ 1,4</output><span>stères estimés</span></div><fieldset class="space-inputs" disabled><legend class="sr-only">Votre rangement et vos bûches</legend><div><label for="space-length">Longueur des bûches</label><select id="space-length"><option value="25">25 cm</option><option value="33" selected>33 cm</option><option value="50">50 cm</option></select></div><div><label for="space-width">Largeur <output id="width-value">100 cm</output></label><input id="space-width" type="range" min="50" max="400" step="10" value="100"></div><div><label for="space-depth">Profondeur <output id="depth-value">100 cm</output></label><input id="space-depth" type="range" min="20" max="150" step="5" value="100"></div><div><label for="space-height">Hauteur <output id="height-value">100 cm</output></label><input id="space-height" type="range" min="20" max="200" step="10" value="100"></div></fieldset><a class="button" id="use-space" href="/reservation/">Préparer ma demande <span aria-hidden="true">↗</span></a><noscript><p>Le calcul nécessite JavaScript. Vous pouvez communiquer vos dimensions directement dans la demande.</p></noscript></div></section>
<section class="photo-pair section">{photo('fibres','Gros plan sur les fibres du bois de Coppey')}{photo('sacs-bois','Bûches de bois rassemblées au dépôt Coppey')}</section>
<section class="faq section"><h2>Les bonnes questions,<br>avant le premier feu.</h2><div><details><summary>Quelle longueur choisir ?</summary><p>Suivez la longueur maximale prévue pour votre appareil. Vous pouvez indiquer la longueur souhaitée dans votre demande ou demander conseil à Coppey.</p></details><details><summary>Quel est le prix du bois ?</summary><p>Le prix dépend du bois disponible, du format, de la quantité et des modalités de livraison. Demandez une proposition qui précise l’unité facturée et les éventuels frais.</p></details><details><summary>Le bois est-il disponible pour mon prochain séjour ?</summary><p>Précisez votre période souhaitée. Coppey vous confirmera la disponibilité, l’état du bois proposé et le délai avant toute réservation.</p></details></div></section>{cta()}
'''
write('bois-de-feu','Bois de feu : choisir ses bûches | Coppey','Découvrez le bois de Coppey, préparez le choix de vos bûches et estimez vos besoins en stères avant de faire une demande.',bois)
livraison=f'''
<section class="page-head"><a class="back-link" href="/">Accueil / Votre livraison</a><h1>Du bois de feu.<br>Jusqu’à chez vous ?</h1><p>À Verbier, dans le Val de Bagnes ou ailleurs en Bas-Valais : préparons votre demande de livraison. La desserte et les modalités sont confirmées avec Coppey.</p></section>
<section class="delivery-story section"><div>{photo('depot','Bois et équipements au dépôt Coppey, entourés de montagnes',eager=True)}</div><div><h2>À Verbier,<br>l’accès compte aussi.</h2><p>Pour un chalet, un appartement ou une résidence, une bonne demande précise où le véhicule peut s’arrêter et où le bois doit arriver.</p><p>Distance à parcourir, escaliers, route étroite, accès hivernal : indiquez ce qui peut influencer la livraison. Cela permet à Coppey de confirmer une solution et son prix.</p><a class="button" href="/reservation/?localite=Verbier">Ma demande pour Verbier <span aria-hidden="true">↗</span></a></div></section>
<section class="delivery-notes section"><h2>Une livraison<br>bien préparée.</h2><div class="note-list"><article><span aria-hidden="true">01</span><h3>Votre localité</h3><p>Le village, le quartier et la période souhaitée. Pour commencer, pas besoin de votre adresse complète.</p></article><article><span aria-hidden="true">02</span><h3>Votre besoin</h3><p>La longueur, une quantité si vous la connaissez, ou les dimensions de votre rangement.</p></article><article><span aria-hidden="true">03</span><h3>Le bon point de dépôt</h3><p>L’accès du véhicule, la distance au rangement et la manutention souhaitée sont à préciser ensemble.</p></article></div></section>
<section class="territory section"><div><h2>Le Val de Bagnes.<br>Et votre adresse.</h2><p>Vous cherchez du bois de feu pour Le Châble, Vollèges, Martigny ou une autre localité du Bas-Valais ? Indiquez-la dans votre demande.</p><p>Le lieu, le volume et la période permettent de vérifier la possibilité de livraison et ses conditions. Aucun créneau n’est réservé automatiquement.</p><a class="text-link" href="/reservation/">Vérifier ma livraison <span aria-hidden="true">↗</span></a></div><div class="territory__art"><img src="/assets/embleme.svg" width="855" height="795" alt="Emblème original Coppey Bois de feu"></div></section>
<section class="faq section"><h2>On règle les détails<br>avant de charger.</h2><div><details><summary>Quels sont les frais de livraison ?</summary><p>Ils sont à confirmer selon votre localité, la quantité et les contraintes d’accès. Demandez le total, bois et transport compris, avant d’accepter la proposition.</p></details><details><summary>Le bois est-il rangé sur place ?</summary><p>Précisez si vous souhaitez uniquement un dépôt ou une aide pour la manutention et le rangement. La prestation possible et son coût doivent être convenus avec Coppey.</p></details><details><summary>Puis-je retirer le bois ?</summary><p>Demandez à Coppey si un retrait est possible, à quel endroit et sur quel rendez-vous. Ne vous déplacez pas sans confirmation.</p></details></div></section>{cta('On organise votre prochain feu ?')}
'''
write('livraison','Bois de feu à Verbier : préparer sa livraison | Coppey','Préparez une demande de livraison de bois à Verbier, dans le Val de Bagnes ou en Bas-Valais. Localité, accès au chalet et conditions à confirmer.',livraison)
reservation='''
<section class="request-head page-head"><a class="back-link" href="/">Accueil / Votre demande</a><h1>Votre prochain feu,<br>on le prépare ensemble.</h1><p>Quelques détails, un message. Coppey vous confirme le bois disponible, le prix et les possibilités de livraison.</p></section>
<section class="request-layout section"><form id="wood-request"><fieldset id="request-fields" disabled><legend class="sr-only">Préparer une demande de bois de feu</legend><div class="field-row"><div class="field"><label for="first-name">Votre prénom <span aria-hidden="true">*</span></label><input id="first-name" name="prenom" required maxlength="80" autocomplete="given-name" placeholder="Votre prénom"></div><div class="field"><label for="locality">Votre localité</label><input id="locality" name="localite" maxlength="100" autocomplete="address-level2" placeholder="Verbier, Le Châble…"></div></div><div class="field"><label for="length">Longueur souhaitée</label><select id="length" name="longueur"><option value="conseil">J’aimerais un conseil<option value="25">25 cm</option><option value="33">33 cm</option><option value="50">50 cm</option><option value="autre">Une autre longueur</option></select><p class="field-help">Un souhait à vérifier avec Coppey selon les formats disponibles.</p></div><div class="field" id="other-length-field" hidden><label for="other-length">Autre longueur, en cm</label><input id="other-length" name="autreLongueur" type="number" min="1" max="200" step="1" disabled inputmode="numeric"></div><div class="field"><label for="quantity">Quantité souhaitée en stères</label><input id="quantity" name="quantite" maxlength="160" placeholder="Par exemple : 2 stères, ou à définir ensemble"><p class="field-help">Vous ne savez pas ? Laissez vide, on vous conseille.</p><p class="field-help" id="space-estimate-note" hidden></p></div><div class="field"><label for="timing">Pour quand ?</label><input id="timing" name="periode" maxlength="120" placeholder="Avant mon séjour, cet automne…"></div><div class="field"><label for="message">Une précision ?</label><textarea id="message" name="precision" rows="4" maxlength="1000" placeholder="Votre foyer, l’accès au chalet, votre besoin de livraison ou de retrait…"></textarea></div><button class="button" type="submit" id="prepare-message" disabled>Préparer mon message <span aria-hidden="true">↗</span></button><p class="field-help">Votre demande ne vaut pas réservation. Le prix, la disponibilité et le délai restent à confirmer.</p></fieldset><noscript><p>Pour préparer un message, activez JavaScript. Vous pouvez aussi joindre Coppey directement au <a href="tel:+41792903493">+41 79 290 34 93</a>.</p></noscript></form><aside class="request-aside"><div id="request-summary"><img src="/assets/buches-creme.svg" width="96" height="102" alt=""><h2>De la place<br>pour du bois.</h2><p>Une petite réserve ou un besoin à préciser ? On en parle.</p><div class="request-progress" aria-hidden="true"><span></span><span></span><span></span></div><p class="small-copy" id="request-hint">Votre message se compose ici, à votre rythme.</p></div><div id="message-result" hidden><h2>Voilà votre message.</h2><label class="sr-only" for="message-preview">Message préparé pour WhatsApp</label><textarea readonly id="message-preview" rows="12"></textarea><a id="whatsapp-send" class="button button--light" rel="noopener noreferrer" referrerpolicy="no-referrer" target="_blank">Continuer sur WhatsApp <span aria-hidden="true">↗</span></a><button id="copy-message" class="copy-button" type="button">Copier le message</button><p class="small-copy">Les détails saisis sont transmis à WhatsApp à l’ouverture du lien. Relisez le message puis envoyez-le vous-même.</p><p id="copy-status" class="small-copy" role="status"></p></div></aside></section>
<section class="direct-contact"><p>Vous préférez en parler directement ?</p><a href="tel:+41792903493">+41 79 290 34 93</a></section>
'''
write('reservation','Demande de bois de feu sur WhatsApp | Coppey','Préparez votre demande de bois de feu : longueur, quantité, localité et période souhaitées. Continuez ensuite sur WhatsApp avec Coppey.',reservation)
privacy='''<section class="page-head"><a class="back-link" href="/">Accueil / Confidentialité</a><h1>Votre demande,<br>vos informations.</h1></section><article class="prose section"><h2>Un message préparé dans votre navigateur</h2><p>Le formulaire compose votre texte sur votre appareil. Il ne transmet pas vos champs à une base de données du site et ne les conserve pas dans le stockage du navigateur.</p><h2>Continuer sur WhatsApp</h2><p>Lorsque vous choisissez « Continuer sur WhatsApp », les informations que vous avez saisies sont incluses dans le lien transmis à WhatsApp. Vous choisissez ensuite d’envoyer le message. WhatsApp applique ses propres conditions de traitement des données.</p><p>Pour limiter les informations partagées lors du premier contact, votre prénom et votre besoin suffisent. L’adresse complète n’est pas demandée par le formulaire.</p><h2>La bulle de contact</h2><p>Un repère temporaire dans votre navigateur évite de réafficher la bulle d’aide pendant votre session. Il ne contient aucune information saisie dans le formulaire.</p><h2>Mesure d’audience et services externes</h2><p>Cette version du site ne comporte pas de traceur publicitaire ni d’outil de mesure d’audience. Si la police Stolzl est chargée depuis Adobe Fonts, votre navigateur contacte les serveurs Adobe pour l’afficher.</p><h2>Contact</h2><p>Pour toute question concernant une demande adressée à Coppey Bois de feu, contactez le <a href="tel:+41792903493">+41 79 290 34 93</a>.</p></article>'''
write('confidentialite','Confidentialité | Coppey Bois de feu','Comprendre comment le préparateur de demande Coppey utilise vos informations et ouvre un message sur WhatsApp.',privacy)
